using Microsoft.Data.Sqlite;
namespace VailACServer;
public sealed class Database {
 readonly string cs;
 public Database(string path) {
  cs=new SqliteConnectionStringBuilder{DataSource=Path.GetFullPath(path),Mode=SqliteOpenMode.ReadWriteCreate}.ToString();
  using var c=Open();using var q=c.CreateCommand();
  q.CommandText="PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS bans(player_id TEXT PRIMARY KEY,machine_id TEXT,reason TEXT NOT NULL,created_utc TEXT NOT NULL); CREATE TABLE IF NOT EXISTS violations(id INTEGER PRIMARY KEY AUTOINCREMENT,player_id TEXT NOT NULL,machine_id TEXT,code INTEGER NOT NULL,details TEXT NOT NULL,score INTEGER NOT NULL,created_utc TEXT NOT NULL); CREATE TABLE IF NOT EXISTS grants(player_id TEXT PRIMARY KEY,can_fly INTEGER NOT NULL DEFAULT 0,can_teleport INTEGER NOT NULL DEFAULT 0,can_menu INTEGER NOT NULL DEFAULT 0,max_speed REAL,max_vertical REAL,note TEXT);";q.ExecuteNonQuery();
 }
 SqliteConnection Open(){var c=new SqliteConnection(cs);c.Open();return c;}
 public bool IsBanned(string p,string? m=null){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT 1 FROM bans WHERE player_id=$p OR ($m IS NOT NULL AND machine_id=$m) LIMIT 1";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$m",(object?)m??DBNull.Value);return q.ExecuteScalar()!=null;}
 public void Ban(string p,string? m,string reason){using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO bans VALUES($p,$m,$r,$t) ON CONFLICT(player_id) DO UPDATE SET machine_id=excluded.machine_id,reason=excluded.reason,created_utc=excluded.created_utc";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$m",(object?)m??DBNull.Value);q.Parameters.AddWithValue("$r",reason);q.Parameters.AddWithValue("$t",DateTimeOffset.UtcNow.ToString("O"));q.ExecuteNonQuery();}
 public void Unban(string p){using var c=Open();using var q=c.CreateCommand();q.CommandText="DELETE FROM bans WHERE player_id=$p";q.Parameters.AddWithValue("$p",p);q.ExecuteNonQuery();}
 public void Violation(string p,string? m,int code,string details,int score){using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO violations(player_id,machine_id,code,details,score,created_utc) VALUES($p,$m,$c,$d,$s,$t)";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$m",(object?)m??DBNull.Value);q.Parameters.AddWithValue("$c",code);q.Parameters.AddWithValue("$d",details);q.Parameters.AddWithValue("$s",score);q.Parameters.AddWithValue("$t",DateTimeOffset.UtcNow.ToString("O"));q.ExecuteNonQuery();}
 public List<ViolationRecord> Violations(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT id,player_id,machine_id,code,details,score,created_utc FROM violations ORDER BY id DESC LIMIT 300";using var r=q.ExecuteReader();var a=new List<ViolationRecord>();while(r.Read())a.Add(new(r.GetInt64(0),r.GetString(1),r.IsDBNull(2)?null:r.GetString(2),r.GetInt32(3),r.GetString(4),r.GetInt32(5),DateTimeOffset.Parse(r.GetString(6))));return a;}
 public List<object> Bans(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT player_id,machine_id,reason,created_utc FROM bans ORDER BY created_utc DESC";using var r=q.ExecuteReader();var a=new List<object>();while(r.Read())a.Add(new{playerId=r.GetString(0),machineId=r.IsDBNull(1)?null:r.GetString(1),reason=r.GetString(2),createdAt=r.GetString(3)});return a;}
 public PlayerPolicy Policy(string p,double speed,double vertical,double teleport){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT can_fly,can_teleport,can_menu,max_speed,max_vertical,note FROM grants WHERE player_id=$p";q.Parameters.AddWithValue("$p",p);using var r=q.ExecuteReader();if(!r.Read())return new(p,false,false,false,speed,vertical,teleport,null);return new(p,r.GetInt32(0)!=0,r.GetInt32(1)!=0,r.GetInt32(2)!=0,r.IsDBNull(3)?speed:r.GetDouble(3),r.IsDBNull(4)?vertical:r.GetDouble(4),teleport,r.IsDBNull(5)?null:r.GetString(5));}
 public void Grant(string p,GrantRequest x,double speed,double vertical){var old=Policy(p,speed,vertical,8);using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO grants VALUES($p,$f,$t,$m,$s,$v,$n) ON CONFLICT(player_id) DO UPDATE SET can_fly=excluded.can_fly,can_teleport=excluded.can_teleport,can_menu=excluded.can_menu,max_speed=excluded.max_speed,max_vertical=excluded.max_vertical,note=excluded.note";q.Parameters.AddWithValue("$p",p);q.Parameters.AddWithValue("$f",(x.CanFly??old.CanFly)?1:0);q.Parameters.AddWithValue("$t",(x.CanTeleport??old.CanTeleport)?1:0);q.Parameters.AddWithValue("$m",(x.CanOpenAdminMenu??old.CanOpenAdminMenu)?1:0);q.Parameters.AddWithValue("$s",(object?)(x.MaxSpeed is >0 and <100?x.MaxSpeed:old.MaxSpeed)??DBNull.Value);q.Parameters.AddWithValue("$v",(object?)(x.MaxVerticalSpeed is >0 and <100?x.MaxVerticalSpeed:old.MaxVerticalSpeed)??DBNull.Value);q.Parameters.AddWithValue("$n",(object?)(x.Note ?? old.Note) ?? DBNull.Value);q.ExecuteNonQuery();}
}
